head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.gAcptNo;
scwin.gIsurCd;

//var gDate ;

// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
// 
// ********************************************************************

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.vScrenID = 'ULDSTF35108.xml';X < !정보--;
셋팅-- > function() {
    scwin.gAcptNo = $c.frame.path("../").scwin.gAcptNo;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    //alert("자식창:"+gAcptNo+","+ gIsurCd);

} < !정보--;
데이타;
읽어오기-- > function() {
    var url = "/UnfaithfulDesign.do?method=readUnfaithful" + "&inputMessageId=NFAITHINFO_INOUT" + "&outputMessageId=NFAITHINFO_INOUT" + "&ACPT_NO=" + scwin.gAcptNo + "&ISUR_CD=" + scwin.gIsurCd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_nfaith_info.DataID = encodeURI(url);
    dts_nfaith_info.reset();
};
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Update = function() {
    var vOccrDd = $c.stf.getObjectValue(edt_occr_dd);
    if (vOccrDd.length < 8) {
        $c.win.alert("날짜를 올바르게 입력하시오.");
        edt_occr_dd.focus();
        return;
    }
    dts_nfaith.insertRow();
    dts_nfaith.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_nfaith.setCellData(1, "ISUR_CD", scwin.gIsurCd);
    dts_nfaith.setCellData(1, "RSN_OCCR_DD", vOccrDd);

    //alert(dts_nfaith.text);

    var vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer == true) {
        //alert(dts_again.text);
        tr_nfaith_info.Action = "/UnfaithfulDesign.do?method=modifyUnfaithful&inputMessageId=NFAITHINFO_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        tr_nfaith_info.KeyName = "toinb_dataid4";
        tr_nfaith_info.KeyValue = "JSP(I:pInput=dts_nfaith)";
        tr_nfaith_info.Post();
    }
};
scwin.img_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_save_onclick = function() {
    scwin.fn_Update();
};
scwin.img_occr_dd_onclick = function() {
    popUpCalendar2(edt_occr_dd);
};
scwin.dts_nfaith_info_OnLoadError = function() {
    $c.stf.alert_error(dts_nfaith_info);
};
scwin.tr_nfaith_info_OnSuccess = async function() {
    $c.win.alert("성공적으로 저장 되었습니다.");
    await $c.frame.CloseFrame();

    // 부모창 reload 처리해야함
    $c.frame.path("../").fn_Search();
};
scwin.tr_nfaith_info_OnFail = function() {
    $c.win.alert('tr_nfaith_info.OnFail() :' + tr_nfaith_info.ErrorMsg);
    dts_nfaith.Reset();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    fn_GetParentValue();

    // 가우스헤더 셋팅
    dts_nfaith_info.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NFAITHINFO_INOUT";
    dts_nfaith_info.reset();
    // 가우스헤더 셋팅
    dts_nfaith.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NFAITHINFO_INOUT";
    dts_nfaith.reset();

    //  정보 읽어오기
    fn_ReadInfo();
};
